field = [c for c in value.columns if c not in ("Manufacturer", "Count")][0]
m = str(value["Manufacturer"].iloc[0]).upper() if "Manufacturer" in value.columns else ""
raw = value[field].iloc[0]
text = "\\".join(map(str, raw)) if isinstance(raw, (list, tuple)) else str(raw)
label = params.get("label") or field

def matches(needle):
    if "|" in needle:
        return any(part.strip() in text for part in needle.split("|"))
    return all(part.strip() in text for part in needle.split("+"))

required = {
    "SIEMENS": params.get("siemens_contains"),
    "PHILIPS": params.get("philips_contains"),
    "GE": params.get("ge_contains"),
}
for vendor, needle in required.items():
    if vendor in m:
        if needle and not matches(needle):
            raise ValidationError(f"{vendor.title()} {label} should contain '{needle}'. Found: {text}")
        break
